//! Raw bindings to the llama.cpp commit pinned in
//! `third_party/llama.cpp/HARBOR_PIN.json` (decision 0022, phase 4).
//!
//! Generated by bindgen over `llama.h`, `gguf.h`, the Harbor C shims
//! (`wrapper_common.h`, feature `common`) and `mtmd.h` / `mtmd-helper.h`
//! (feature `mtmd`). Use the safe wrapper in `harbor_llama`.

#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(unpredictable_function_pointer_comparisons)]
#![allow(clippy::all)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
include!(concat!(env!("OUT_DIR"), "/pin.rs"));
